        public void solve(int testNumber, InputReader in, PrintWriter out) throws IOException {
            int k = in.nextInt();
            long ans = 0;
            for (int i = 1; i <=k; i++) {
                for (int j = 1; j <= i; j++) {
                    for (int l = j; l <= i ; l++) {
                        long g = gcdMultiple(i,j,l);
                        if (findUnique(i,j,l) == 1) {
                            ans += g;
                        }
                        if (findUnique(i,j,l) == 2) {
                            ans += g*3;
