        ret[i] = (char) (chars[i] + n - 'Z' + 'A' - 1);
      } else {
        ret[i] = (char) (chars[i] + n);
      }
    }
    StringBuilder result = new StringBuilder();
    for (char c : ret) {
      result.append(c);
    }
    System.out.println(result.toString());
  }
}

