			if (A[i] == target) {
				sum+=add;
				target = -1;
			}

			//C確認
			if (A[i] < C.length) {
				target = A[i] + 1;
				add = C[A[i]];
			}else {
				target = -1;
			}

		}

		System.out.println(sum);
	}

}

