                System.out.println("0");
                return;
            }
        }

        int oldNum = 0;
        long count = 1;

        for (int i = 0; i < m; i++) {
            int num = broken[i];
            count = count * fibonacci((num - 1) - oldNum) % MOD;
            oldNum = num + 1;
        }

        count = count * fibonacci(n - oldNum) % MOD;

        System.out.println(count);
    }

    public static long fibonacci(long n) {
        long num1 = 1;
        long num2 = 1;
        long tmp = 1;

        for (long i = 1; i < n; i++) {
            tmp = (num1 + num2) % MOD;
            num1 = num2;
            num2 = tmp;
        }

        return tmp;
    }
}

