        dp[0] = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 1; j <= k; j++) {
                final int arrIdx = Math.min(i + j, n - 1);
                dp[i + j] = Math.min(dp[i + j], dp[i] + Math.abs(arr[arrIdx] - arr[i]));
            }
